/* From Uiverse.io by alexruix - Tags: simple, gradient, card, hover, smooth, dark, about me */
.__UIV_SCOPE__ .card {
  color: #1b1b1b;
  width: 190px;
  height: 254px;
  position: relative;
  outline: 6px solid #f5f5f5;
  border-radius: 8px;
  line-height: 150%;
  padding: 16px;
  background: #ff930f;
  background-blend-mode: multiply;
  background: linear-gradient(to top, #ff930f, #ffcc33);
  transition: background-color 1s ease-in-out;
  overflow: hidden;
}

.__UIV_SCOPE__ .card-front {
  bottom: 16px;
  left: 0;
  position: absolute;
  width: 100%;
  text-align: center;
  transition: transform 1s cubic-bezier(0.785, 0.135, 0.150, 0.860);
}

.__UIV_SCOPE__ .card-back {
  transform: translateX(120%);
  transition: transform 1s cubic-bezier(0.785, 0.135, 0.150, 0.860);
}


/*Text*/
.__UIV_SCOPE__ .title {
  font-size: 1.3rem;
  font-weight: bold;
}
/*Text divider*/
.__UIV_SCOPE__ .title::after {
  content: "";
  display: block;
  width: 50%;
  border-radius: 50%;
  height: 2px;
  margin: 2px auto;
  background-color: #1b1b1b;
}


/*Hover*/
.__UIV_SCOPE__ .card:hover {
  background-color: #1b1b1b25;
}

.__UIV_SCOPE__ .card:hover .card-front {
  transform: translateX(-100%);
}

.__UIV_SCOPE__ .card:hover .card-back {
  transform: translateX(0);
}
